window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-153"]=[{"id":"set2-mdL3E-nV","fingerprint":"0eaed3f39bd7a928","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este mecanismul patogenic ce stă la baza formării chistului dermoid?","options":[{"id":"A","text":"Transformarea chistică a incluziilor epiteliale restante la locul de unire a arcurilor branhiale."},{"id":"B","text":"O reacție inflamatorie cronică ce duce la blocarea unui duct excretor."},{"id":"C","text":"Este o leziune dobândită, apărută ca urmare a unui traumatism la nivelul planșeului bucal."},{"id":"D","text":"O proliferare aberantă a țesutului glandular salivar minor din planșeul bucal."},{"id":"E","text":"Degenerarea chistică a resturilor epiteliale odontogene Malassez."}],"correct":["A"],"pages":[629],"source":"set-2"},{"id":"set2-dchCpNX7","fingerprint":"ec1ab2d93d44629a","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații referitoare la localizarea chistului dermoid sunt adevărate?","options":[{"id":"A","text":"Localizarea tipică este în planșeul bucal, pe linia mediană."},{"id":"B","text":"La nivelul limbii, apare extrem de rar, tot pe linia mediană."},{"id":"C","text":"Se poate extinde din planșeul bucal în loja submentonieră."},{"id":"D","text":"Poate fi localizat paramedian în planșeul bucal."},{"id":"E","text":"Localizarea la nivelul palatului dur este frecventă la adulții tineri."}],"correct":["A","B","C","D"],"pages":[629],"source":"set-2"},{"id":"set2-nfD0letq","fingerprint":"44ea9e9c0e3f376e","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Un pacient tânăr prezintă o formațiune asimptomatică, cu creștere lentă, în planșeul bucal anterior. Care sunt caracteristicile clinice concordante cu diagnosticul de chist dermoid oral?","options":[{"id":"A","text":"Creșterea este rapidă și dureroasă, cauzând frecvent tulburări de deglutiție."},{"id":"B","text":"Mucoasa acoperitoare este nemodificată, fiind doar destinsă de formațiune."},{"id":"C","text":"Formațiunea are dimensiuni ce pot varia de la câțiva milimetri până la 10-12 cm."},{"id":"D","text":"Prezența sa poate determina etalarea frenului lingual."},{"id":"E","text":"Apariția sa este limitată strict la perioada neonatală."}],"correct":["B","C","D"],"pages":[629],"source":"set-2"},{"id":"set2-DxGdJrkG","fingerprint":"de11bcea46a1dc4c","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este raportul anatomic specific al chistului dermoid oral față de mușchiul milohioidian?","options":[{"id":"A","text":"Se dezvoltă deasupra planului mușchiului milohioidian, în planșeul bucal anterior."},{"id":"B","text":"Este localizat paramedian, perforând mușchiul milohioidian."},{"id":"C","text":"Se dezvoltă întotdeauna și exclusiv sub planul mușchiului milohioidian."},{"id":"D","text":"Infiltrează corpul muscular al mușchiului milohioidian."},{"id":"E","text":"Se localizează constant în loja submandibulară, fără a avea raport direct cu mușchiul milohioidian."}],"correct":["A"],"pages":[629],"source":"set-2"},{"id":"set2-EN815Wwq","fingerprint":"23961f8cd113a26e","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt caracteristicile clinice ale unui chist dermoid neperforat, localizat în planșeul bucal?","options":[{"id":"A","text":"La perforare, elimină un conținut lichidian clar sau sero-hemoragic."},{"id":"B","text":"La presiune, lasă godeu."},{"id":"C","text":"Are o consistență fluctuentă și este situat de obicei paramedian."},{"id":"D","text":"Are o consistență ferm-elastică și este mobil pe planurile adiacente."},{"id":"E","text":"Creșterea sa poate împinge limba în sus și posterior, generând tulburări funcționale."}],"correct":["B","D","E"],"pages":[630],"source":"set-2"},{"id":"set2-vUwJd6uC","fingerprint":"664868f847b8b116","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce aspect clinic este specific chistului dermoid care se dezvoltă sub planul mușchiului milohioidian?","options":[{"id":"A","text":"Prezența unor fistule cervicale mediane."},{"id":"B","text":"Mobilizarea formațiunii în timpul deglutiției și la protruzia limbii."},{"id":"C","text":"Tegumente supraiacente destinse, lucioase și hiperemice."},{"id":"D","text":"O deformație submentonieră care conferă un aspect de „bărbie dublă”."},{"id":"E","text":"Consistență fluctuentă, cu conținut ce poate fi împins într-un compartiment superior."}],"correct":["D"],"pages":[630],"source":"set-2"},{"id":"set2-YrF8xOIB","fingerprint":"bee8f88901a5f59c","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afecțiuni sunt luate în considerare în diagnosticul diferențial al unui chist dermoid localizat în planșeul bucal?","options":[{"id":"A","text":"Chistul teratoid."},{"id":"B","text":"Chistul canalului tireoglos."},{"id":"C","text":"Tumorile glandelor sublinguale."},{"id":"D","text":"Adenita submentonieră."},{"id":"E","text":"Ranula sublinguală."}],"correct":["A","C","E"],"pages":[630],"source":"set-2"},{"id":"set2-Lz3Q5XGQ","fingerprint":"330e834d8a977f8c","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care element clinic este cel mai sugestiv pentru a diferenția un chist de canal tireoglos de un chist dermoid suprahioidian?","options":[{"id":"A","text":"Lipsa modificărilor la nivelul tegumentelor supraiacente."},{"id":"B","text":"Evoluția rapidă și tendința de infiltrare a țesuturilor adiacente."},{"id":"C","text":"Prezența unei deformații submentoniere de tip „bărbie dublă”."},{"id":"D","text":"Consistența ferm-elastică la palpare."},{"id":"E","text":"Mobilizarea în timpul deglutiției și la protruzia limbii."}],"correct":["E"],"pages":[630],"source":"set-2"},{"id":"set2-_LtPNth9","fingerprint":"866c295638013d19","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce afirmații referitoare la tratamentul chistului dermoid sunt corecte?","options":[{"id":"A","text":"Dificultatea intervenției chirurgicale este crescută în cazurile suprainfectate."},{"id":"B","text":"Tratamentul este strict chirurgical și vizează extirparea în totalitate a formațiunii."},{"id":"C","text":"Tratamentul de elecție pentru formele mici, asimptomatice, este monitorizarea periodică."},{"id":"D","text":"Abordul poate fi oral sau cutanat, iar pentru formele mari se poate folosi un abord mixt."},{"id":"E","text":"Recidivele după o extirpare completă sunt considerate extrem de rare."}],"correct":["A","B","D","E"],"pages":[630],"source":"set-2"},{"id":"set2-RorDYU1O","fingerprint":"750d4981ecf13951","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt informațiile corecte referitoare la patogenia chistului branhial?","options":[{"id":"A","text":"Este o incluzie epitelială restantă a unui pliu ectodermic al celei de-a treia fante branhiale."},{"id":"B","text":"Apare prin transformarea chistică a epiteliului embrionar restant de la nivelul canalului tireoglos rezidual."},{"id":"C","text":"Mecanismul său etiologic este diferit de cel al chistului canalului tireoglos."},{"id":"D","text":"Se localizează de-a lungul mușchiului sternocleidomastoidian."},{"id":"E","text":"O teorie patogenică implică degenerarea chistică a unor incluziuni de epiteliu salivar la nivelul unui ganglion limfatic."}],"correct":["C","E"],"pages":[630],"source":"set-2"},{"id":"set2-GC2NWreQ","fingerprint":"c8eb8d294b88d3f3","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt caracteristicile epidemiologice și de debut ale chistului branhial?","options":[{"id":"A","text":"Apare în prima copilărie și are tendință de remisie odată cu creșterea."},{"id":"B","text":"Are o evoluție extrem de lentă, de-a lungul mai multor ani."},{"id":"C","text":"Statistic, apare exclusiv pe partea stângă a gâtului."},{"id":"D","text":"Apare cu predilecție la adolescenți sau adulți tineri, mai frecvent la sexul feminin."},{"id":"E","text":"Se dezvoltă rapid volumetric, în aproximativ 1-3 săptămâni, deseori corelat cu o infecție a căilor aeriene superioare."}],"correct":["D","E"],"pages":[631],"source":"set-2"},{"id":"set2-AV9BFL2R","fingerprint":"75c5b799d77ed1a3","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce caracteristici clinice sunt specifice unui chist branhial neinfectat la palpare?","options":[{"id":"A","text":"Prezintă caracter pulsatil."},{"id":"B","text":"Nu se mobilizează în timpul deglutiției."},{"id":"C","text":"Este nedureros."},{"id":"D","text":"Este fixat și infiltrează planurile adiacente."},{"id":"E","text":"Are o consistență moale sau fluctuantă."}],"correct":["B","C","E"],"pages":[631],"source":"set-2"},{"id":"set2-AHd38DIh","fingerprint":"88b2c2149cf4dd17","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este localizarea anatomică cea mai frecventă a chistului branhial?","options":[{"id":"A","text":"Periangulomandibular sau în treimea inferioară a mușchiului sterno-cleido-mastoidian."},{"id":"B","text":"Pre- și sub-sternocleidomastoidian, în treimea superioară și medie, la nivelul bifurcației carotice."},{"id":"C","text":"În loja parotidiană, având caracter pulsatil."},{"id":"D","text":"Paramedian în planșeul bucal, deasupra mușchiului milohioidian."},{"id":"E","text":"Strict în treimea inferioară a mușchiului sterno-cleido-mastoidian."}],"correct":["B"],"pages":[631],"source":"set-2"},{"id":"set2-M18AEWVi","fingerprint":"27bdc313151100b7","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"În contextul diagnosticului diferențial al unei mase laterocervicale, ce element clinic orientează în mod specific către o adenopatie metastatică?","options":[{"id":"A","text":"Prezența poliadenopatiei cervicale în absența unei tumori primare în teritoriul de drenaj."},{"id":"B","text":"Apariția în prima copilărie și lipsa unei delimitări clare."},{"id":"C","text":"Consistența fermă și prezența unei tumori maligne orale sau faringiene."},{"id":"D","text":"Evoluția extrem de lentă și consistența moale, dar nefluctuentă."},{"id":"E","text":"Caracterul pulsatil al formațiunii."}],"correct":["C"],"pages":[631],"source":"set-2"},{"id":"set2-XBuTVqvr","fingerprint":"bf702034b42317b8","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce afirmații sunt corecte în legătură cu tratamentul chirurgical al chistului branhial?","options":[{"id":"A","text":"Incizia verticală de-a lungul marginii anterioare a mușchiului sternocleidomastoidian este tehnica standard actuală."},{"id":"B","text":"Incizia orizontală este preferată pentru a disimula cicatricea postoperatorie într-un pliu natural al gâtului."},{"id":"C","text":"Extirparea în totalitate a chistului previne recidiva."},{"id":"D","text":"Intervenția este deosebit de dificilă în cazul chisturilor suprainfectate din cauza aderențelor la structurile adiacente."},{"id":"E","text":"Chistul nu are raporturi anatomice importante, ceea ce facilitează extirparea."}],"correct":["B","C","D"],"pages":[631],"source":"set-2"},{"id":"set2-az30VBIP","fingerprint":"2b9a6248841effd4","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este explicația acceptată pentru cazurile de \"malignizare\" a chistului branhial?","options":[{"id":"A","text":"Sunt considerate a fi, de fapt, metastaze ganglionare cu conținut chistic, provenite de la tumori maligne orale sau orofaringiene."},{"id":"B","text":"Reprezintă o transformare neoplazică primară a epiteliului chistic."},{"id":"C","text":"Este o complicație care apare exclusiv după extirparea incompletă a chistului."},{"id":"D","text":"Malignizarea este un proces comun, care duce la dezvoltarea de limfoame non-hodgkiniene."},{"id":"E","text":"Fenomenul este observat doar în cazul chisturilor care au fost suprainfectate cronic."}],"correct":["A"],"pages":[631],"source":"set-2"},{"id":"set2-JNZOxVS3","fingerprint":"d7213eface55db90","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este originea patogenică a ranulei?","options":[{"id":"A","text":"Rezultă din transformarea chistică a epiteliului unui canal de excreție al glandei sublinguale."},{"id":"B","text":"Este cauzată de obstrucția canalului Wharton la originea sa în glanda submandibulară."},{"id":"C","text":"Este un sialochist specific glandelor salivare mici."},{"id":"D","text":"Este o metastază chistică a unei tumori de glandă salivară."},{"id":"E","text":"Se dezvoltă din resturi epiteliale ale arcurilor branhiale."}],"correct":["A"],"pages":[631],"source":"set-2"},{"id":"set2-4m_PVSwF","fingerprint":"f42366f2df954577","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce semne clinice sunt caracteristice pentru o ranulă sublinguală?","options":[{"id":"A","text":"Se află deasupra mușchiului milohioidian."},{"id":"B","text":"Este situată în treimea superioară a mușchiului sternocleidomastoidian."},{"id":"C","text":"Este o formațiune chistică localizată paramedian în planșeul bucal."},{"id":"D","text":"Este o masă fermă, fixată și dureroasă la palpare."},{"id":"E","text":"Prezintă o colorație tipică albăstruie datorită vizibilității conținutului lichidian prin transparența mucoasei."}],"correct":["A","C","E"],"pages":[631],"source":"set-2"},{"id":"set2-mCkqaGpK","fingerprint":"912f1e1d65c21928","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt caracteristicile clinice ale unei ranule sublinguale necomplicate?","options":[{"id":"A","text":"Se poate perfora spontan, eliminând un lichid similar cu saliva, dar cu ptialină absentă sau în cantitate mică."},{"id":"B","text":"Este o formațiune chistică localizată paramedian în planșeul bucal."},{"id":"C","text":"La palpare, aderă la corticala linguală a mandibulei."},{"id":"D","text":"Prezintă o consistență fluctuantă și este nedureroasă."},{"id":"E","text":"Mucoasa acoperitoare are aspect normal, nefiind vizibil conținutul formațiunii."}],"correct":["A","B","D"],"pages":[632],"source":"set-2"},{"id":"set2-ixSzG57y","fingerprint":"6f5356d0d39fd867","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce reprezintă elementul structural definitoriu pentru o ranulă „în bisac” (plonjantă)?","options":[{"id":"A","text":"Dezvoltarea exclusivă sub mușchiul milohioidian, aderentă la glanda submandibulară."},{"id":"B","text":"Tegumentele acoperitoare sunt întotdeauna aderente și de culoare albăstruie."},{"id":"C","text":"Localizarea strict pe linia mediană, cu strangulare la nivelul frenului lingual."},{"id":"D","text":"Prezența a două compartimente, unul în planșeul bucal și celălalt în regiunea suprahioidiană, comunicante între ele."},{"id":"E","text":"Suprainfectarea constantă a chistului, cu fenomene supurative locale."}],"correct":["D"],"pages":[632],"source":"set-2"},{"id":"set2-ya8VuAw5","fingerprint":"d17668df759a0baa","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"În timpul examinării clinice a unei ranule „în bisac”, ce efect are exercitarea presiunii pe compartimentul suprahioidian (inferior)?","options":[{"id":"A","text":"Tegumentele de la nivelul gâtului devin aderente."},{"id":"B","text":"Apare o durere acută, specifică fenomenelor de colică salivară."},{"id":"C","text":"Formațiunea chistică bombează submucos în planșeul bucal."},{"id":"D","text":"Compartimentul inferior se mărește în volum."},{"id":"E","text":"Se produce o perforare spontană cu eliminarea conținutului salivar."}],"correct":["C"],"pages":[632],"source":"set-2"},{"id":"set2-8qFtz3mz","fingerprint":"32170bcc4ef62a59","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afecțiuni sunt considerate în diagnosticul diferențial al unei ranule sublinguale?","options":[{"id":"A","text":"Chistul dermoid."},{"id":"B","text":"Tumorile benigne ale glandelor sublinguale."},{"id":"C","text":"Dilatațiile chistice ale canalului Wharton."},{"id":"D","text":"Fenomenele supurative ale regiunii submentoniere."},{"id":"E","text":"Tumorile chistice ale regiunii submandibulare."}],"correct":["A","B","C"],"pages":[632],"source":"set-2"},{"id":"set2-tnCGkR_1","fingerprint":"813e364bbaeee1bb","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Prin ce se deosebește clinic un chist dermoid de o ranulă sublinguală?","options":[{"id":"A","text":"Tumefacția în cazul chistului dermoid este legată de orarul meselor."},{"id":"B","text":"Chistul dermoid aderă la corticala linguală a mandibulei."},{"id":"C","text":"Chistul dermoid este localizat pe linia mediană și conținutul chistic este de culoare gălbuie."},{"id":"D","text":"Chistul dermoid are o consistență fluctuentă și culoare albăstruie."},{"id":"E","text":"Chistul dermoid are o evoluție mai îndelungată decât ranula."}],"correct":["C"],"pages":[632],"source":"set-2"},{"id":"set2-s24YLw_Z","fingerprint":"7b9401ee62967f7a","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este tratamentul chirurgical standard pentru ranulă, având ca scop prevenirea recidivelor?","options":[{"id":"A","text":"Doar incizia și drenajul conținutului lichidian vâscos."},{"id":"B","text":"Extirparea ranulei, inclusiv a membranei chistice, împreună cu glanda sublinguală implicată."},{"id":"C","text":"Marsupializarea, pentru a restabili drenajul glandei sublinguale."},{"id":"D","text":"Extirparea ranulei în bisac printr-un abord exclusiv oral."},{"id":"E","text":"Extirparea membranei chistice cu păstrarea glandei sublinguale implicate."}],"correct":["B"],"pages":[632],"source":"set-2"},{"id":"set2-wNrd3Q3d","fingerprint":"a79482efdd560d03","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce afirmație este corectă cu privire la marsupializarea ranulei?","options":[{"id":"A","text":"Scopul principal este îndepărtarea glandei sublinguale."},{"id":"B","text":"Este indicată în toate tipurile de ranulă, inclusiv cea plonjantă."},{"id":"C","text":"Este o variantă terapeutică modernă, frecvent utilizată în prezent."},{"id":"D","text":"Constă în extirparea completă a membranei chistice."},{"id":"E","text":"Este o procedură cu o rată ridicată de recidivă."}],"correct":["E"],"pages":[632],"source":"set-2"},{"id":"set2-x05OnGOK","fingerprint":"b2eafbba64bfb0bb","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce elemente anatomice din planșeul bucal trebuie identificate, izolate și conservate în timpul extirpării chirurgicale a unei ranule sublinguale?","options":[{"id":"A","text":"Nervul lingual."},{"id":"B","text":"Mușchiul milohioidian."},{"id":"C","text":"Canalul Wharton."},{"id":"D","text":"Osul hioid."},{"id":"E","text":"Artera și vena linguală."}],"correct":["A","C","E"],"pages":[632],"source":"set-2"},{"id":"set2-rVfeeY5y","fingerprint":"1b4eb14c65bb878a","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este abordarea chirurgicală recomandată pentru o ranula suprahioidiană cu evoluție strict sub mușchiul milohioidian?","options":[{"id":"A","text":"Un abord chirurgical cervical, submandibular, care implică adesea extirparea glandei submandibulare aderente."},{"id":"B","text":"Un abord chirurgical mixt, oral și cutanat, ca primă intenție."},{"id":"C","text":"Atunci când pacientul prezintă un risc crescut de sângerare postoperatorie."},{"id":"D","text":"Un abord chirurgical strict oral, pentru a minimiza cicatricile cervicale."},{"id":"E","text":"Extirparea formațiunii împreună cu glanda sublinguală de origine, printr-un abord cervical."}],"correct":["A"],"pages":[633],"source":"set-2"},{"id":"set2-KxwgJdfV","fingerprint":"377927bd31f77319","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații descriu corect natura granulomului piogen?","options":[{"id":"A","text":"Este o hiperplazie reactivă a mucoasei orale, formată din țesut granulativ."},{"id":"B","text":"Este o tumoră malignă în faza de debut, cu evoluție inițial rapidă."},{"id":"C","text":"Denumirea de botriomicom, deși acceptată istoric, se bazează pe conceptul eronat al unei etiologii infecțioase."},{"id":"D","text":"O infecție cu botriococ, conform denumirii sale istorice."},{"id":"E","text":"Denumirea sa este improprie, deoarece nu este un granulom propriu-zis și nu are caracter piogen."}],"correct":["A","C","E"],"pages":[633],"source":"set-2"},{"id":"set2-EzGFyxzN","fingerprint":"9e27fa48067ea615","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt caracteristicile clinice ale granulomului piogen?","options":[{"id":"A","text":"La palpare, are o consistență moale, este nedureros și sângerează ușor la traumatisme minore."},{"id":"B","text":"Evoluția sa este lentă și progresivă, fără a stagna vreodată."},{"id":"C","text":"Leziunile vechi sunt mai fibrozate, având o culoare roz-roșie."},{"id":"D","text":"Un factor iritativ mecanic cronic, legat de traumatizarea mucoasei labiale la contactul arcadelor dentare."},{"id":"E","text":"Leziunile recente sunt mai intens vascularizate și au o culoare de la roz la roșu intens (purpuriu)."}],"correct":["A","C","E"],"pages":[633],"source":"set-2"},{"id":"set2-amFyx8mH","fingerprint":"693d8a36927b2c59","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce reprezintă epulisul granulomatos și unde este localizat cel mai frecvent?","options":[{"id":"A","text":"Este o leziune cu celule gigante, de culoare albăstruie, localizată exclusiv pe mucoasa linguală."},{"id":"B","text":"Este cea mai frecventă formă de granulom piogen oral, apărând în spațiul interdentar, de obicei pe versantul vestibular."},{"id":"C","text":"În toate cazurile de ranula „în bisac”, pentru a asigura o vizibilitate maximă."},{"id":"D","text":"Este un fibrom osifiant periferic, cu consistență fermă, asociat cu o igienă orală precară."},{"id":"E","text":"Este o formă de granulom specifică sarcinii, cauzată de modificări hormonale, care apare pe mucoasa jugală."}],"correct":["B"],"pages":[633],"source":"set-2"},{"id":"set2-UN3DAI4Z","fingerprint":"f683e72804b88864","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații despre granulomul gravidei (tumora de sarcină) sunt adevărate?","options":[{"id":"A","text":"Incidența sa este mai accentuată în trimestrul al treilea de sarcină."},{"id":"B","text":"După naștere, leziunea poate involua sau chiar dispărea complet."},{"id":"C","text":"Este cauzat exclusiv de deficiențe nutriționale, fără influențe hormonale."},{"id":"D","text":"Cauza probabilă este de natură hormonală, prin creșterea nivelului de estrogeni și progesteron."},{"id":"E","text":"Cauza probabilă este de natură hormonală, o scădere a nivelului de estrogeni și progesteron în timpul sarcinii."}],"correct":["A","B","D"],"pages":[633],"source":"set-2"},{"id":"set2-j7cNv7fS","fingerprint":"ab3c3d3abf25b0e8","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"În diagnosticul diferențial al epulisului granulomatos, ce caracteristici clinice sunt specifice granulomului periferic cu celule gigante (epulis cu celule gigante)?","options":[{"id":"A","text":"O culoare mai albăstruie."},{"id":"B","text":"Prezența unei carii subgingivale sau a unei lucrări protetice deficitare."},{"id":"C","text":"Apariția doar în legătură cu un dinte prezent pe arcadă."},{"id":"D","text":"O consistență mai fermă și o culoare roz deschis."},{"id":"E","text":"Sângerare abundentă la cel mai mic traumatism."}],"correct":["A"],"pages":[633],"source":"set-2"},{"id":"set2-MCw5Gg_5","fingerprint":"8f7b9fc85ed67636","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"În ce situație este necesar un abord chirurgical mixt, oral și cutanat, pentru o ranula „în bisac”?","options":[{"id":"A","text":"O culoare mai albăstruie."},{"id":"B","text":"Atunci când ranula aderă la glanda submandibulară, necesitând extirparea concomitentă a acesteia."},{"id":"C","text":"Sângerare la cel mai mic traumatism."},{"id":"D","text":"Atunci când formațiunea chistică este strangulată de fibrele mușchiului milohioidian și nu poate fi extirpată complet doar prin abord cervical."},{"id":"E","text":"O consistență mai fermă și o culoare roz deschis."}],"correct":["D"],"pages":[633],"source":"set-2"},{"id":"set2-JIsjGnJW","fingerprint":"c9a0009db462e829","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este factorul iritativ cel mai frecvent asociat cu apariția botriomicomului la nivelul mucoasei labiale, linguale sau jugale?","options":[{"id":"A","text":"Inflamația cronică pe fondul unei igiene orale deficitare"},{"id":"B","text":"Lucrare protetică fixă adaptată deficitar"},{"id":"C","text":"Apariția doar în legătură cu un dinte prezent pe arcadă."},{"id":"D","text":"Traumatizarea mucoasei în momentul contactului arcadelor dentare."},{"id":"E","text":"Carie subgingivală"}],"correct":["D"],"pages":[633],"source":"set-2"},{"id":"set2-V8059HeC","fingerprint":"de2c24cfc6ccf7bd","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"În diagnosticul diferențial al granulomului piogen cu localizări orale (botriomicom), care dintre următoarele entități se caracterizează printr-o consistență mai fermă și o culoare roz deschis?","options":[{"id":"A","text":"Granulomul periferic cu celule gigante"},{"id":"B","text":"Formele de debut ale tumorilor maligne"},{"id":"C","text":"Tumorile maligne ale mucoasei crestei alveolare"},{"id":"D","text":"Fibromul mucoasei orale"},{"id":"E","text":"Papilomul mucoasei orale"}],"correct":["D"],"pages":[634],"source":"set-2"},{"id":"set2-rEeH6rLV","fingerprint":"bab9644b327a1f09","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele principii terapeutice sunt corecte în managementul granulomului piogen gingival (epulis granulomatos)?","options":[{"id":"A","text":"Extracția dinților adiacenți leziunii este obligatorie pentru a preveni recidiva."},{"id":"B","text":"Extirparea chirurgicală se realizează cu margini de siguranță de aproximativ 2 mm."},{"id":"C","text":"Plaga postoperatorie se vindecă per secundam."},{"id":"D","text":"Periostul subiacent se conservă pentru a facilita o vindecare mai rapidă."},{"id":"E","text":"Chiuretajul osos se practică în toate cazurile, indiferent de consistența osului."}],"correct":["B","C"],"pages":[634],"source":"set-2"},{"id":"set2-L5Luazsp","fingerprint":"e71904c28a815626","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este o diferență notabilă în managementul plăgii postoperatorii între granulomul piogen gingival (epulis granulomatos) și cel cu alte localizări orale (botriomicom)?","options":[{"id":"A","text":"Plaga rezultată după extirparea botriomicomului se poate închide prin sutură primară, în timp ce cea a epulisului se vindecă per secundam."},{"id":"B","text":"Ambele plăgi se vindecă exclusiv per secundam și se protejează cu ciment parodontal."},{"id":"C","text":"Îndepărtarea factorului iritativ local este necesară doar în cazul epulisului granulomatos."},{"id":"D","text":"Plaga post-epulis nu necesită protecție, spre deosebire de cea post-botriomicom."},{"id":"E","text":"Sutura primară este metoda de elecție pentru epulisul granulomatos, iar vindecarea secundară pentru botriomicom."}],"correct":["A"],"pages":[634],"source":"set-2"},{"id":"set2-LbMblRkW","fingerprint":"e06f327054a9c402","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce factor este asociat cu un risc mai mare de recidivă a granulomului piogen?","options":[{"id":"A","text":"Localizarea leziunii la nivelul mucoasei jugale."},{"id":"B","text":"Utilizarea cimentului parodontal pentru protejarea plăgii."},{"id":"C","text":"Apariția leziunii în timpul sarcinii."},{"id":"D","text":"Extirparea incompletă a leziunii și neîndepărtarea factorului iritativ local."},{"id":"E","text":"Vindecarea plăgii per secundam."}],"correct":["C","D"],"pages":[634],"source":"set-2"},{"id":"set2-ZtdoLL39","fingerprint":"05111ca46ba3bc1f","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații despre granulomul periferic cu celule gigante sunt adevărate?","options":[{"id":"A","text":"Se localizează exclusiv la nivelul crestei alveolare."},{"id":"B","text":"Este o leziune hiperplazică ce derivă din periost sau din structurile ligamentului parodontal."},{"id":"C","text":"Are o etiologie infecțioasă virală."},{"id":"D","text":"Leziunea este o manifestare clinică frecvent asociată cu hiperparatiroidismul."},{"id":"E","text":"Apare cel mai frecvent la copii și adolescenți."}],"correct":["A","B"],"pages":[634],"source":"set-2"},{"id":"set2-Dj79POoF","fingerprint":"fcaeb6dc0305b807","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce aspect radiologic este caracteristic pentru granulomul periferic cu celule gigante?","options":[{"id":"A","text":"O eroziune superficială a crestei alveolare cu aspect de „os ciupit”."},{"id":"B","text":"Absența oricărei modificări osoase vizibile radiologic."},{"id":"C","text":"O zonă de osteoscleroză difuză la nivelul osului subiacent."},{"id":"D","text":"O reacție periostală cu depunere de os în straturi, de tip \"bulb de ceapă\"."},{"id":"E","text":"O radiotransparență bine delimitată, uniloculară, similară unui chist."}],"correct":["A"],"pages":[634],"source":"set-2"},{"id":"set2-Iqi1h9RE","fingerprint":"0df7273e733e82ca","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Cu ce afecțiuni poate fi confundat granulomul periferic cu celule gigante, din punct de vedere clinic sau radiologic?","options":[{"id":"A","text":"Datorită culorii roz deschis, se poate confunda cu un fibrom al mucoasei orale."},{"id":"B","text":"Cu epulisul granulomatos, care are culoarea roz deschis."},{"id":"C","text":"Clinic, pe creasta alveolară edentată, poate semăna cu o tumoră vasculară."},{"id":"D","text":"Este frecvent confundat cu granulomul central cu celule gigante, deoarece ambele sunt asociate cu hiperparatiroidism."},{"id":"E","text":"Aspectul său radiologic poate fi similar cu cel al formelor de debut ale tumorilor maligne ale gingivomucoasei."}],"correct":["C","E"],"pages":[634],"source":"set-2"},{"id":"set2-80dIW09g","fingerprint":"3fa50d6ef75b24bf","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care dintre următoarele afirmații referitoare la leziunile cu care se face diagnosticul diferențial al granulomului periferic cu celule gigante este adevărată?","options":[{"id":"A","text":"Diagnosticul de certitudine între granulomul piogen și fibromul osifiant periferic se poate stabili pe baza caracteristicilor clinice."},{"id":"B","text":"Tumorile maligne ale mucoasei crestei alveolare nu intră în diagnosticul diferențial în faza de debut."},{"id":"C","text":"Fibromul osifiant periferic este o leziune care poate apărea frecvent și la nivelul crestelor alveolare edentate."},{"id":"D","text":"Fibromul osifiant periferic sângerează la traumatisme minore și are o consistență redusă."},{"id":"E","text":"Granulomul piogen gingival are o consistență mai redusă, o culoare roz-roșie și sângerează la mici traumatisme."}],"correct":["E"],"pages":[635],"source":"set-2"},{"id":"set2-Uga0lKNj","fingerprint":"d50c46833f7ac35b","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații descriu corect principiile tratamentului chirurgical al granulomului periferic cu celule gigante?","options":[{"id":"A","text":"Vindecarea plăgii postoperatorii se realizează prin sutură primară, pentru a minimiza cicatrizarea."},{"id":"B","text":"Îndepărtarea factorului iritativ local este o componentă obligatorie a tratamentului."},{"id":"C","text":"Extirparea formațiunii se realizează la limita vizibilă a leziunii, conservând periostul subiacent pentru o vindecare rapidă."},{"id":"D","text":"Chiuretajul osos este indicat doar în leziunile asociate dinților, nu și la nivelul crestelor alveolare edentate."},{"id":"E","text":"Rata de recidivă este de aproximativ 10% și este asociată în principal cu neîndepărtarea structurilor dure subiacente afectate."}],"correct":["B","E"],"pages":[635],"source":"set-2"},{"id":"set2-7DXbQjjS","fingerprint":"6566f93ba667b7e6","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce informații despre patogenia și epidemiologia papilomului oral sunt corecte?","options":[{"id":"A","text":"Prezintă o prevalență crescută la sexul masculin și afectează în principal persoanele sub 20 de ani."},{"id":"B","text":"Este cauzat de infecția cu virusul papiloma uman (HPV), tipurile 2, 6 și 11 fiind cel mai frecvent identificate."},{"id":"C","text":"Este o proliferare tumorală benignă a stratului spinos al epiteliului."},{"id":"D","text":"Prezența HPV în cavitatea orală duce invariabil la apariția manifestărilor clinice."},{"id":"E","text":"Modul de transmitere al virusului este bine cunoscut, fiind exclusiv prin contact direct."}],"correct":["B","C"],"pages":[635],"source":"set-2"},{"id":"set2-MNK4X1BQ","fingerprint":"66764a5d31172041","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care dintre următoarele descrie cel mai exact aspectul clinic tipic al unui papilom oral?","options":[{"id":"A","text":"O leziune sesilă, cu bază largă de implantare, de consistență întotdeauna fermă."},{"id":"B","text":"O formațiune tumorală cu creștere exofitică, verucoasă sau conopidiformă, având prelungiri digitiforme."},{"id":"C","text":"O formațiune cu suprafață netedă, de culoare albă, care atinge frecvent dimensiuni de peste 2 cm."},{"id":"D","text":"O leziune de culoare roșiatică, localizată exclusiv la nivelul mucoasei linguale."},{"id":"E","text":"O tumora cu creștere lentă, endofitică, ce ulcerează rapid."}],"correct":["B"],"pages":[635],"source":"set-2"},{"id":"set2-9mgychdt","fingerprint":"7fb516d4b2f139f6","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce caracteristici sunt specifice papilomului sino-nazal?","options":[{"id":"A","text":"Este frecvent asimptomatic, fiind descoperit incidental în timpul unui examen endoscopic sinuzal."},{"id":"B","text":"Include trei variante histopatologice: papilomul scuamos, papilomul inversat și papilomul bazocelular."},{"id":"C","text":"Debutează cu simptome zgomotoase, precum obstrucție nazală severă și epistaxis."},{"id":"D","text":"Una dintre variantele sale histopatologice, papilomul inversat, prezintă un risc de malignizare de 15%."},{"id":"E","text":"Localizarea sa predilectă este la nivelul sinusului maxilar."}],"correct":["A","D","E"],"pages":[635],"source":"set-2"},{"id":"set2-Cv866v7i","fingerprint":"f9f879a26e1b0bca","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care dintre următoarele afecțiuni, utilizată în diagnosticul diferențial al papilomului oral, se caracterizează printr-o suprafață netedă și o mucoasă acoperitoare normală?","options":[{"id":"A","text":"Fibromul mucoasei orale"},{"id":"B","text":"Granulomul piogen"},{"id":"C","text":"Carcinomul verucos în formă de debut"},{"id":"D","text":"Carcinomul spinocelular în formă de debut vegetantă"},{"id":"E","text":"Mucocelul sino-nazal"}],"correct":["A"],"pages":[636],"source":"set-2"},{"id":"set2-fA-RtX5N","fingerprint":"eb523bb1356b2a2a","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce abordare chirurgicală este necesară în cazul unui papilom sino-nazal care a erodat peretele sino-nazal și s-a extins la nivelul sinusului maxilar?","options":[{"id":"A","text":"Chiuretajul leziunii și aplicarea de substanțe caustice."},{"id":"B","text":"Chiuretajul leziunii și aplicarea de substanțe antiseptice."},{"id":"C","text":"Cura radicală a sinusului maxilar pe cale rinologică."},{"id":"D","text":"Tratament expectativ, monitorizând evoluția."},{"id":"E","text":"Extirparea simplă a formațiunii de la nivelul fosei nazale."}],"correct":["C"],"pages":[636],"source":"set-2"},{"id":"set2-85JSTtsI","fingerprint":"cd12c47ebead2920","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații referitoare la papilom și papilomatoză sunt adevărate?","options":[{"id":"A","text":"Papilomul localizat la nivelul tegumentelor cervico-faciale poate avea un aspect clinic asemănător verucii vulgare."},{"id":"B","text":"Apariția a numeroase leziuni papilare este denumită papilomatoză și poate avea localizare orală."},{"id":"C","text":"Riscul de malignizare al papilomului în sine este considerat foarte ridicat."},{"id":"D","text":"Riscul de malignizare al papilomului în sine este considerat scăzut."},{"id":"E","text":"Recidivele papilomului oral sunt frecvente după o extirpare completă."}],"correct":["A","B","D"],"pages":[636],"source":"set-2"},{"id":"set2-qLNnXWPc","fingerprint":"fad4729fe1acd4fb","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce entități sunt luate în considerare în diagnosticul diferențial al papilomului sino-nazal?","options":[{"id":"A","text":"Formele de debut ale tumorilor maligne ale mucoasei sino-nazale."},{"id":"B","text":"Granulomul piogen („botriomicomul”)."},{"id":"C","text":"Fibromul mucoasei orale."},{"id":"D","text":"Fibromul mucoasei vaginale."},{"id":"E","text":"Mucocelul sau sialochistul sino-nazal."}],"correct":["A","E"],"pages":[636],"source":"set-2"},{"id":"set2-Nkqp9kqA","fingerprint":"60818beeea58bfc6","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Referitor la tratamentul și prognosticul papilomului oral, care este conduita corectă?","options":[{"id":"A","text":"Tratamentul nu este necesar, deoarece riscul de malignizare este scăzut."},{"id":"B","text":"Extirparea în totalitate a formațiunii împreună cu baza de implantare."},{"id":"C","text":"Infecția HPV asociată este considerată un factor de risc pentru transformarea malignă a mucoasei."},{"id":"D","text":"Infecția HPV asociată nu este considerată un factor de risc pentru transformarea malignă a mucoasei."},{"id":"E","text":"După extirparea completă, recidivele sunt rare."}],"correct":["B","C","E"],"pages":[636],"source":"set-2"},{"id":"set2-fKZGRwh7","fingerprint":"b4f5b6ebca70ab88","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt caracteristicile patogenice și epidemiologice ale chistului dermoid?","options":[{"id":"A","text":"Se localizează exclusiv în zonele laterale ale gâtului."},{"id":"B","text":"Originea sa este legată de anomaliile de fuziune a mugurilor maxilari."},{"id":"C","text":"Poate fi prezent uneori chiar la naștere."},{"id":"D","text":"Se datorează transformării chistice a incluziilor epiteliale restante de la locul de unire a arcurilor branhiale."},{"id":"E","text":"Apare cel mai frecvent la adulții tineri."}],"correct":["C","D","E"],"pages":[629,630],"source":"set-2"},{"id":"set2-okvfcVvf","fingerprint":"9755e29df223f57f","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele manifestări clinice descriu chistul dermoid cu localizare orală?","options":[{"id":"A","text":"Se dezvoltă sub planul mușchiului milohioidian."},{"id":"B","text":"Mucoasa acoperitoare prezintă ulcerații caracteristice."},{"id":"C","text":"Este o formațiune cu creștere rapidă și puternic simptomatică de la debut."},{"id":"D","text":"Prezintă o consistență ferm-elastică și lasă godeu la presiune."},{"id":"E","text":"Prin creștere, împinge limba spre în sus și spre posterior, inducând tulburări de fonație și respirație."}],"correct":["D","E"],"pages":[629,630],"source":"set-2"},{"id":"set2-DkZww2Nv","fingerprint":"32dc17190cebfcfd","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt particularitățile de localizare ale chistului dermoid?","options":[{"id":"A","text":"Loja submandibulară reprezintă sediul cel mai frecvent de apariție."},{"id":"B","text":"Localizarea tipică este în planșeul bucal, pe linia mediană."},{"id":"C","text":"Poate apărea paramedian la nivelul planșeului bucal."},{"id":"D","text":"Localizarea la nivelul limbii, pe linia mediană, este extrem de rară."},{"id":"E","text":"Se dezvoltă predominant intraosos la nivelul unghiului mandibular."}],"correct":["B","C","D"],"pages":[629,630],"source":"set-2"},{"id":"set2-ZzUOkzcz","fingerprint":"aa1a9ae67caca744","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este consecința clinică principală a dezvoltării chistului dermoid sub planul mușchiului milohioidian?","options":[{"id":"A","text":"Etalează frenul lingual și expune direct în cavitatea orală un conținut cenușiu-gălbui."},{"id":"B","text":"Induce blocajul articulației temporo-mandibulare prin extensie posterioară."},{"id":"C","text":"Se prezintă ca o ulcerație dureroasă la nivelul treimii posterioare a limbii."},{"id":"D","text":"Apare ca o masă tumorală cu creștere rapidă, fixată ferm de tegumentul submandibular."},{"id":"E","text":"Determină o deformație submentonieră care dă aspect de „bărbie dublă”, fără modificarea tegumentelor supraiacente."}],"correct":["E"],"pages":[629,630],"source":"set-2"},{"id":"set2-hDv-0_Hr","fingerprint":"efc1d2e9bbe94c08","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații descriu caracteristicile chistului teratoid în contextul patologiei planșeului bucal?","options":[{"id":"A","text":"Prezintă frecvent un aspect polichistic, interesând părțile moi supraiacente."},{"id":"B","text":"Se asociază frecvent cu fistule cervicale mediane."},{"id":"C","text":"Este practic imposibil de diferențiat clinic de chistul dermoid."},{"id":"D","text":"Consistența sa este mai fermă, uneori palpându-se un conținut dur."},{"id":"E","text":"Are un caracter dobândit, manifestându-se predominant la vârsta adultă."}],"correct":["C","D"],"pages":[630],"source":"set-2"},{"id":"set2-EIZY1vkX","fingerprint":"460b96c6fe64c549","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt elementele clinice ce caracterizează chistul canalului tireoglos în cadrul diagnosticului diferențial al formațiunilor situate sub planul mușchiului milohioidian?","options":[{"id":"A","text":"Conținutul său este împins din compartimentul suprahioidian în cel oral la palparea bimanuală."},{"id":"B","text":"Se mobilizează în timpul protruziei limbii."},{"id":"C","text":"Interesează tegumentele care devin destinse, lucioase și hiperemice."},{"id":"D","text":"Se mobilizează în timpul actului de deglutiție."},{"id":"E","text":"Prezintă frecvent fistule cervicale mediane."}],"correct":["B","D","E"],"pages":[630],"source":"set-2"},{"id":"set2-14MlQtop","fingerprint":"c44cf5b2fdbe5600","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce particularități prezintă tratamentul chirurgical al chistului dermoid?","options":[{"id":"A","text":"Recidivele sunt extrem de frecvente chiar și după extirparea completă a formațiunii chistice."},{"id":"B","text":"Formarea de aderențe prin fibrozare parcelară îngreunează intervenția, în special în caz de suprainfecție în antecedente."},{"id":"C","text":"Abordul chirurgical este exclusiv oral, independent de dimensiunea formațiunii."},{"id":"D","text":"Extirparea poate fi dificilă din cauza extinderii formațiunii către baza limbii."},{"id":"E","text":"Formele de mari dimensiuni necesită uneori un abord mixt, oral și cutanat."}],"correct":["B","D","E"],"pages":[630],"source":"set-2"},{"id":"set2-pUhkciUr","fingerprint":"ab31d525434198fc","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele asocieri între patologiile cervico-faciale și manifestările lor clinice sunt descrise?","options":[{"id":"A","text":"Limfangiomul chistic al planșeului bucal conține un lichid clar sau sero-hemoragic."},{"id":"B","text":"Abcesul lojei submentoniere prezintă o evoluție lentă, fără alterarea stării generale."},{"id":"C","text":"Tumorile glandelor sublinguale sunt situate median și prezintă consistență fluctuentă."},{"id":"D","text":"Adenopatia metastatică submentonieră asociază o consistență fermă cu tendința de infiltrare și fixare la țesuturile adiacente."},{"id":"E","text":"Ranula sublinguală se prezintă ca o formațiune situată paramedian, cu consistență fluctuentă."}],"correct":["A","D","E"],"pages":[630],"source":"set-2"},{"id":"set2-0mPpi4G-","fingerprint":"5441fe08d934696c","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"În diagnosticul diferențial al formațiunilor situate sub planul mușchiului milohioidian, adenopatia metastatică submentonieră se diferențiază prin:","options":[{"id":"A","text":"Evoluția mai rapidă."},{"id":"B","text":"Mobilizarea sincronă cu protruzia limbii."},{"id":"C","text":"Prezența unei tumori maligne în teritoriul de drenaj, precum buza sau limba."},{"id":"D","text":"Consistența sa fluctuentă și aspectul polichistic."},{"id":"E","text":"Tendința de infiltrare și fixare la țesuturile adiacente."}],"correct":["A","C","E"],"pages":[630],"source":"set-2"},{"id":"set2-NIK5AUaj","fingerprint":"1c521707a665179f","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt afirmațiile adevărate privind etiopatogenia și dezvoltarea chistului branhial?","options":[{"id":"A","text":"Derivă din incluzia epitelială restantă a unui pliu endodermic al celei de-a doua fante branhiale."},{"id":"B","text":"Examenul histopatologic al peretelui chistului evidențiază o absență totală a elementelor limfoide."},{"id":"C","text":"Este localizat de-a lungul mușchiului sternocleidomastoidian."},{"id":"D","text":"Se poate dezvolta din incluziuni ale unui epiteliu de tip salivar restante la nivelul unui ganglion limfatic."},{"id":"E","text":"Apare prin transformarea chistică a epiteliului embrionar restant la nivelul canalului tireoglos rezidual."}],"correct":["A","C","D"],"pages":[630],"source":"set-2"},{"id":"set2-IJrEUM4B","fingerprint":"c35077257cb219ad","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele caracteristici clinice descriu evoluția și prezentarea chistului branhial?","options":[{"id":"A","text":"Dezvoltarea sa volumetrică se desfășoară extrem de lent, pe parcursul a câțiva ani de la debut."},{"id":"B","text":"Formațiunea tumorală se mobilizează simultan cu mișcările capului și în timpul deglutiției."},{"id":"C","text":"Este o masă tumorală aderentă la planul tegumentar, dureroasă constant, indiferent de prezența suprainfecției."},{"id":"D","text":"Creșterea rapidă este deseori corelată de pacienți cu o infecție acută a căilor aeriene superioare."},{"id":"E","text":"Prezintă raporturi anatomice de vecinătate cu arterele carotide internă și externă."}],"correct":["D","E"],"pages":[631],"source":"set-2"},{"id":"set2-WhOdhhuT","fingerprint":"a08d49db33221962","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt afirmațiile adevărate privind elementele de diagnostic diferențial pentru formațiunile tumorale laterocervicale?","options":[{"id":"A","text":"Limfangioamele cervicale sunt bine delimitate și prezintă tendință de creștere accelerată la vârsta adultă."},{"id":"B","text":"Adenopatiile din limfoame prezintă o consistență fermă, în absența unei tumori maligne primare în teritoriul de drenaj limfatic."},{"id":"C","text":"Tumorile glomusului carotidian se pot diferenția net prin caracterul lor pulsatil."},{"id":"D","text":"Adenopatiile metastatice cervicale de mari dimensiuni se disting printr-o mare mobilitate și lipsa infiltrării planurilor adiacente."},{"id":"E","text":"Lipomul laterocervical are o evoluție extrem de lentă și prezintă o consistență moale, nefluctuentă."}],"correct":["B","C","E"],"pages":[631],"source":"set-2"},{"id":"set2--vIz6kgP","fingerprint":"a5d5fab1d1633fc8","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce repere anatomice și principii chirurgicale sunt vizate în tratamentul chistului branhial?","options":[{"id":"A","text":"Polul superior al chistului branhial necesită disecția de peretele lateral al faringelui și de vârful apofizei stiloide."},{"id":"B","text":"Dificultatea extirpării scade semnificativ atunci când structura chistică este suprainfectată."},{"id":"C","text":"Chistul branhial extirpat în totalitate este marcat de o lipsă a recidivelor postoperatorii."},{"id":"D","text":"Abordul chirurgical optim presupune o incizie tegumentară verticală pe marginea anterioară a mușchiului sternocleidomastoidian."},{"id":"E","text":"Extirparea formațiunii implică detașarea acesteia de pachetul vasculo-nervos al gâtului."}],"correct":["A","C","E"],"pages":[631],"source":"set-2"},{"id":"set2-yvVYPd2F","fingerprint":"22b65b07ba83bb77","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este localizarea anatomică tipică în care se dezvoltă preponderent chistul branhial necomplicat?","options":[{"id":"A","text":"Treimea inferioară a mușchiului sternocleidomastoidian, fără raporturi cu alte vase cervicale."},{"id":"B","text":"Posterior de trahee, coborând către mediastinul superior pe un traiect endodermic preexistent."},{"id":"C","text":"În loja glandei submandibulare, anterior de pântecele anterior al mușchiului digastric."},{"id":"D","text":"La nivel pre- și sub-sternocleidomastoidian, în treimea superioară și medie, în dreptul bifurcației carotice."},{"id":"E","text":"Strict pe linia mediană a gâtului, substituind structura glandei tiroide."}],"correct":["D"],"pages":[631],"source":"set-2"},{"id":"set2-9s0JF7A6","fingerprint":"7018583f057cfe2f","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt caracteristicile clinice și patogenice ale ranulei sublinguale?","options":[{"id":"A","text":"Rezultă prin transformarea chistică a epiteliului unuia dintre canalele de excreție ale glandei sublinguale."},{"id":"B","text":"Este localizată paramedian în planșeul bucal, deasupra mușchiului milohioidian."},{"id":"C","text":"După o eventuală perforare spontană și decomprimare, formațiunea chistică se reface în câteva zile."},{"id":"D","text":"La palpare, chistul are consistență fluctuantă și este puternic aderent la corticala linguală a mandibulei."},{"id":"E","text":"Lichidul din interior conține o cantitate mare de ptialină, fiind perfect identic biochimic cu saliva."}],"correct":["A","B","C"],"pages":[631],"source":"set-2"},{"id":"set2-cgno0sL-","fingerprint":"13573a77cff59a15","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este afirmația adevărată referitoare la patogenia și aspectul clinic al ranulei „în bisac”?","options":[{"id":"A","text":"Trecerea formațiunii chistice în regiunea suprahioidiană se realizează printre fibrele mușchiului milohioidian sau prin interstițiul hiogloso-milohioidian."},{"id":"B","text":"Tegumentele care acoperă compartimentul inferior al chistului sunt eritematoase, indurate și puternic aderente de planurile profunde."},{"id":"C","text":"Compartimentul supramilohioidian al chistului este întotdeauna foarte evident clinic la simpla inspecție a cavității orale."},{"id":"D","text":"Presiunea exercitată la nivelul compartimentului inferior determină colabarea acestuia și evacuarea masivă a salivei în cavitatea orală."},{"id":"E","text":"Este o variantă clinică frecventă, în care formațiunea chistică se dezvoltă exclusiv în loja submandibulară."}],"correct":["A"],"pages":[632],"source":"set-2"},{"id":"set2-j97fMCcz","fingerprint":"8f11a3d952f66be4","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt elementele care ajută la diagnosticul diferențial corect al ranulei cu alte afecțiuni ale regiunii orale și cervicale?","options":[{"id":"A","text":"Chistul teratoid prezintă un aspect de masă nodulară translucidă, strict legată de glandele salivare mici."},{"id":"B","text":"Chistul dermoid are o predilecție pentru localizarea paramediană, prezintă o consistență dură și o colorație purpurie."},{"id":"C","text":"Hemangioamele și limfangioamele planșeului bucal prezintă o evoluție clinică de scurtă durată, asociată frecvent cu colici salivare acute."},{"id":"D","text":"Dilatațiile chistice ale canalului Wharton sunt caracterizate de o tumefacție influențată de orarul meselor, fiind însoțite de fenomene de colică salivară."},{"id":"E","text":"Chistul gastrointestinal heterotopic apare mai rar în planșeul anterior, luând aspectul unei mase nodulare."}],"correct":["D","E"],"pages":[632],"source":"set-2"},{"id":"set2-PiqkSJoK","fingerprint":"df272dd5ea7bb395","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații referitoare la tratamentul ranulei sunt corecte?","options":[{"id":"A","text":"Extirparea pe cale orală a ranulei sublinguale impune identificarea și conservarea canalului Wharton, a nervului lingual și a pachetului vascular lingual."},{"id":"B","text":"Marsupializarea reprezintă tratamentul chirurgical de elecție și cel mai frecvent utilizat în prezent, datorită lipsei recidivelor."},{"id":"C","text":"Ranula suprahioidiană dezvoltată strict sub mușchiul milohioidian necesită abord submandibular și este adesea extirpată cu glanda submandibulară."},{"id":"D","text":"Pentru a preveni recidivele, ranula sublinguală se extirpă chirurgical lăsând întotdeauna pe loc glanda sublinguală pentru a menține secreția."},{"id":"E","text":"Ranula „în bisac” poate impune un abord chirurgical mixt (oral și cutanat) atunci când formațiunea chistică este strangulată de mușchiul milohioidian."}],"correct":["A","C","E"],"pages":[633],"source":"set-2"},{"id":"set2-a_FZeD30","fingerprint":"bf1c11318acfeb72","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este deosebirea patogenică principală dintre ranulă și sialochist?","options":[{"id":"A","text":"Ranula rezultă prin transformarea chistică a epiteliului unui duct de excreție al glandei sublinguale, iar sialochistul este caracteristic glandelor salivare mici."},{"id":"B","text":"Ranula se dezvoltă prin afectarea glandelor salivare mici, în timp ce sialochistul apare exclusiv la nivelul glandei parotide."},{"id":"C","text":"Ambele formațiuni chistice au originea în epiteliul glandei sublinguale, singura diferență fiind extinderea dincolo de mușchiul milohioidian în cazul sialochistului."},{"id":"D","text":"Sialochistul provine din transformarea porțiunii terminale a canalului Wharton, pe când ranula se dezvoltă din ductele interlobulare ale glandei submandibulare."},{"id":"E","text":"Ranula este declanșată obligatoriu de un proces infecțios, pe când sialochistul rezultă din defecte de organogeneză în viața intrauterină."}],"correct":["A"],"pages":[631],"source":"set-2"},{"id":"set2-eeNMlw9w","fingerprint":"7020e3929761fad0","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care dintre următoarele afirmații descriu caracteristicile clinice și evolutive ale granulomului piogen oral?","options":[{"id":"A","text":"Leziunile vechi au o colorație roz-roșie, având un grad mai mare de fibrozare."},{"id":"B","text":"Prezintă sângerare la cele mai mici traumatisme, ca o consecință a vascularizației intense."},{"id":"C","text":"Evoluția leziunii presupune o creștere lentă, progresivă și constantă pe parcursul mai multor ani."},{"id":"D","text":"Este o leziune cu etiologie infecțioasă bacteriană, determinată de botriococ."},{"id":"E","text":"La palpare, formațiunea pseudotumorală prezintă o consistență moale și este nedureroasă."}],"correct":["A","B","E"],"pages":[633],"source":"set-2"},{"id":"set2-2xHH-BE4","fingerprint":"eda884d462cff116","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce evoluție are în mod caracteristic granulomul de sarcină în perioada imediat următoare nașterii?","options":[{"id":"A","text":"Involuează progresiv, existând posibilitatea de a dispărea în totalitate."},{"id":"B","text":"Crește exponențial în volum, determinând o asimetrie facială severă."},{"id":"C","text":"Se calcifică la nivelul centrului lezional, transformându-se într-o masă de consistență dură."},{"id":"D","text":"Se transformă rapid într-un fibrom osifiant periferic pe fondul modificărilor osoase."},{"id":"E","text":"Sângerează spontan și masiv, necesitând chiuretaj osos extins de urgență."}],"correct":["A"],"pages":[633],"source":"set-2"},{"id":"set2-b7XD_axL","fingerprint":"5b8cc4cf7d469df3","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Diagnosticul diferențial al granulomului piogen gingival se realizează cu următoarele afecțiuni:","options":[{"id":"A","text":"Fibromul osifiant periferic."},{"id":"B","text":"Tumorile maligne ale mucoasei crestei alveolare."},{"id":"C","text":"Fibromul mucoasei orale."},{"id":"D","text":"Papilomul mucoasei orale."},{"id":"E","text":"Granulomul periferic cu celule gigante."}],"correct":["A","B","E"],"pages":[633],"source":"set-2"},{"id":"set2-qNApa6KT","fingerprint":"010a14b6004da38e","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt procedurile terapeutice și indicațiile chirurgicale în cazul granulomului piogen gingival (epulis granulomatos)?","options":[{"id":"A","text":"Se practică obligatoriu extracția dintelui adiacent la toți pacienții pentru a reduce riscul de recidivă."},{"id":"B","text":"Vindecarea plăgii postoperatorii se face per secundam, protejându-se cu meșă iodoformată sau ciment parodontal."},{"id":"C","text":"Extirparea chirurgicală se realizează strict prin menținerea intactă a periostului pentru a favoriza vascularizația osoasă."},{"id":"D","text":"Extirparea chirurgicală a formațiunii presupune respectarea unor margini de siguranță de aproximativ 2 mm."},{"id":"E","text":"Dacă osul alveolar subiacent prezintă un aspect moale și demineralizat, se efectuează chiuretajul osos până în țesut sănătos."}],"correct":["B","D","E"],"pages":[634],"source":"set-2"},{"id":"set2-1Fd9Z-IG","fingerprint":"a7a84e5673748540","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Ce caracteristici de ordin clinic și topografic definesc leziunea denumită clasic „botriomicom”?","options":[{"id":"A","text":"Constituie o leziune cu tendință constantă de malignizare, necesitând rezecție osoasă în bloc."},{"id":"B","text":"Prezintă în mod invariabil o nuanță albăstruie și este apanajul exclusiv al trimestrului al treilea de sarcină."},{"id":"C","text":"Apare predilect în spațiul interdentar, prezentând o legătură strânsă cu cariile dentare subgingivale."},{"id":"D","text":"Are o consistență extrem de fermă și sângerează exclusiv sub efectul manipulării instrumentale aspre."},{"id":"E","text":"Reprezintă o hiperplazie cu apariție la nivelul mucoasei labiale, linguale sau jugale, pe fondul iritației mecanice cronice."}],"correct":["E"],"pages":[633],"source":"set-2"},{"id":"set2-mcy9efXR","fingerprint":"356355dba26ec6c8","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt trăsăturile etiopatogenice și clinice ale granulomului periferic cu celule gigante?","options":[{"id":"A","text":"Leziunea este asociată în mod direct cu hiperparatiroidismul sever."},{"id":"B","text":"Localizarea este exclusivă la nivelul crestei alveolare."},{"id":"C","text":"Derivă din periost sau din structurile ligamentului parodontal."},{"id":"D","text":"Culoarea caracteristică a formațiunii este roz deschis, sângerând cu ușurință la mici traumatisme."},{"id":"E","text":"Se prezintă la pacienții edentați ca o leziune de formă ovoidală sau fuziformă, similară unei tumori vasculare."}],"correct":["B","C","E"],"pages":[634],"source":"set-2"},{"id":"set2-lQC7G8eS","fingerprint":"3b5982904b478c97","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este trăsătura distinctivă a fibromului osifiant periferic în cadrul diagnosticului diferențial cu granulomul periferic cu celule gigante?","options":[{"id":"A","text":"Consistența sa este mai redusă."},{"id":"B","text":"Culoarea formațiunii este roșie-violacee."},{"id":"C","text":"Diagnosticul de certitudine se stabilește exclusiv pe baza aspectului radiologic."},{"id":"D","text":"Sângerează abundent la traumatisme minore."},{"id":"E","text":"Nu apare decât în legătură cu prezența unui dinte."}],"correct":["E"],"pages":[635],"source":"set-2"},{"id":"set2-EARLNbF2","fingerprint":"333c4866d1d6c75e","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt principiile conduitei terapeutice în cazul granulomului periferic cu celule gigante?","options":[{"id":"A","text":"Chiuretajul osos până în țesut sănătos este obligatoriu și în localizările la nivelul crestei alveolare edentate."},{"id":"B","text":"Conservarea periostului subiacent pentru a asigura vascularizația lamboului gingival."},{"id":"C","text":"Vindecarea plăgii se realizează prin sutură primară directă, fiind contraindicată protejarea cu meșă iodoformată."},{"id":"D","text":"Îndepărtarea obligatorie a factorului iritativ local."},{"id":"E","text":"Extirparea în totalitate a formațiunii cu margini libere de aproximativ 2 mm în țesut sănătos."}],"correct":["A","D","E"],"pages":[635],"source":"set-2"},{"id":"set2-X9buoMO3","fingerprint":"ba444b29d747a4d4","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce elemente pot fi observate la examenul radiologic și clinic al dinților și osului alveolar în prezența granulomului periferic cu celule gigante?","options":[{"id":"A","text":"Eroziune superficială cu aspect de \"os ciupit\" la nivelul crestei alveolare subiacente zonelor edentate."},{"id":"B","text":"Apariția constantă a leziunilor carioase subgingivale ca urmare directă a expansiunii tumorale."},{"id":"C","text":"Liza osoasă caracteristică a limbusului alveolar subiacent dintelui cauzal."},{"id":"D","text":"Osteogeneza reactivă care determină hipertrofia limbusului alveolar adiacent."},{"id":"E","text":"Afectarea suprafeței radiculare a dintelui cauzal în unele situații."}],"correct":["A","C","E"],"pages":[634],"source":"set-2"},{"id":"set2-1NeUI6Kf","fingerprint":"018ff4438f1cef14","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care dintre următoarele descrieri corespunde cu precizie aspectului clinic și evolutiv al granulomului periferic cu celule gigante?","options":[{"id":"A","text":"Dimensiunile leziunii variază în mod constant între 5 și 7 cm, indiferent de stadiul evolutiv."},{"id":"B","text":"Leziunea este predominant întâlnită la bărbați tineri cu igienă orală deficitară."},{"id":"C","text":"Creșterea leziunii este exofitică și pediculată, sângerând spontan din cauza consistenței reduse."},{"id":"D","text":"Aspectul radiologic al osului procesului alveolar exclude confuzia cu tumorile maligne ale gingivomucoasei."},{"id":"E","text":"Formațiunea are o consistență ferm-elastică, o culoare roșie-violacee și este de obicei sesilă."}],"correct":["E"],"pages":[634],"source":"set-2"},{"id":"set2-rH8Oyijj","fingerprint":"b958eb79e6f5f5a6","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt afirmațiile adevărate privind aspectele clinice și patogenice ale papilomului oral?","options":[{"id":"A","text":"Tipurile virale HPV 2, 6 și 11 sunt identificate relativ constant în aceste leziuni."},{"id":"B","text":"Prevalența afecțiunii este semnificativ mai mare la persoanele de sex masculin."},{"id":"C","text":"Dimensiunile formațiunii tumorale depășesc în mod constant 1 cm."},{"id":"D","text":"Proliferarea tumorală benignă afectează predominant stratul cornos al epiteliului."},{"id":"E","text":"Culoarea suprafeței tumorale este determinată de gradul de keratinizare."}],"correct":["A","E"],"pages":[635],"source":"set-2"},{"id":"set2-YpFPB8GY","fingerprint":"539f9da5c169724d","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Care sunt caracteristicile papilomului sino-nazal?","options":[{"id":"A","text":"Este descoperit frecvent în mod întâmplător la un examen endoscopic sinuzal, fiind practic asimptomatic."},{"id":"B","text":"Prezintă trei variante histopatologice: papilomul scuamos, papilomul inversat și papilomul cu celule cilindrice."},{"id":"C","text":"Tratamentul poate presupune cura radicală a sinusului maxilar pe cale rinologică atunci când peretele sino-nazal este desființat."},{"id":"D","text":"Papilomul cu celule cilindrice prezintă un risc de malignizare de 15%."},{"id":"E","text":"Localizarea de elecție la nivelul sinusurilor paranazale este sinusul sfenoidal."}],"correct":["A","B","C"],"pages":[635],"source":"set-2"},{"id":"set2-v4g5gPjz","fingerprint":"ca3a8148bfc68b08","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Cu ce alte afecțiuni trebuie realizat diagnosticul diferențial al papilomului oral?","options":[{"id":"A","text":"Mucocelul sino-nazal, leziune frecvent localizată la nivelul mucoasei jugale."},{"id":"B","text":"Formele de debut ale tumorilor maligne de tip carcinom verucos."},{"id":"C","text":"Formele de debut vegetante ale tumorilor maligne de tip carcinom spinocelular."},{"id":"D","text":"Granulomul piogen, al cărui diagnostic clinic de certitudine îl exclude cu ușurință pe cel de papilom."},{"id":"E","text":"Fibromul mucoasei orale, care se distinge prin suprafața netedă și mucoasa acoperitoare normală."}],"correct":["B","C","E"],"pages":[636],"source":"set-2"},{"id":"set2--EQn9u7A","fingerprint":"cbc0e0c7124c2868","chapterId":"set-2","subchapterId":"set2-7.21","type":"CS","text":"Care este elementul descriptiv caracteristic papilomului?","options":[{"id":"A","text":"Formațiunea este pediculată sau uneori sesilă, cu prelungiri digitiforme și suprafață neregulată."},{"id":"B","text":"Leziunile au de cele mai multe ori dimensiuni ce depășesc constant 2 cm."},{"id":"C","text":"Consistența este strict moale la toate leziunile, din cauza absenței țesutului fibros."},{"id":"D","text":"Formațiunea tumorală prezintă o creștere endofitică, cu invadarea țesuturilor subiacente."},{"id":"E","text":"Localizarea se limitează exclusiv la nivelul mucoasei palatului dur și vălului palatin."}],"correct":["A"],"pages":[635],"source":"set-2"},{"id":"set2-ecLXuLCB","fingerprint":"bd4951b61034c4d8","chapterId":"set-2","subchapterId":"set2-7.21","type":"CM","text":"Ce aspecte sunt asociate tratamentului papiloamelor și formelor clinice particulare?","options":[{"id":"A","text":"Papilomatoza se caracterizează prin apariția unor numeroase leziuni papilare cu localizare tegumentară, orală sau laringiană."},{"id":"B","text":"Riscul de malignizare al papilomului oral în sine este considerat foarte crescut."},{"id":"C","text":"Recidivele după extirparea chirurgicală completă a papilomului oral sunt extrem de frecvente."},{"id":"D","text":"Tratamentul papilomului oral presupune extirparea în totalitate a formațiunii împreună cu baza de implantare."},{"id":"E","text":"Infecția cu HPV reprezintă un factor de risc local aflat în interrelație cu alți factori, fiind discutată în contextul transformării maligne a mucoasei."}],"correct":["A","D","E"],"pages":[636],"source":"set-2"}];
